REF = {x[0]: x[2] for x in GUIDE if x[0] != 'lead'}
REF['install'] = 'Вывод команд установки и запуска показан на рисунке {n}.'


def build(out):
    b = Doc(chap=4, layout=LAYOUT, ref=REF)
    b.px_full = 2496
    b.h1(4, 'Руководство по установке (развертыванию) и использованию программного средства')

    b.h2('4.1 Руководство по установке (развертыванию) программного средства', first=True)
    b.text('Программное средство состоит из сервера на Node.js и базы данных MySQL, а пользователи работают с ним через браузер. Для установки на компьютер с операционной системой Windows 10 или новее требуется следующее программное обеспечение:')
    b.bullets([
        'Node.js версии 20 или новее вместе с менеджером пакетов npm',
        'сервер баз данных MySQL версии 8.0 или новее, с которым устанавливаются утилиты mysql и mysqldump, нужные для резервного копирования',
        'система контроля версий Git для получения исходного кода (вместо неё можно скачать архив проекта)',
        'браузер Яндекс Браузер, Firefox, Chrome или Opera',
    ])
    b.text('Исходный код получают командой git clone из репозитория проекта или распаковывают из архива. Затем под администратором MySQL создаются пользователь taler и две базы данных: рабочая talerbank и talerbank_test для автоматических тестов. Пользователю выдаются все права на обе базы и право RELOAD, которое нужно утилите mysqldump, а параметр сервера log_bin_trust_function_creators разрешает создавать триггеры, защищающие проводки и журнал аудита от изменения.')
    b.text('Дальнейшие действия выполняются в папке проекта в командной строке. Команда npm install загружает библиотеки, команда npm run setup создаёт файл настроек .env со случайными секретными ключами, команда npm run db:migrate создаёт таблицы и справочники из SQL-скриптов, а npm run db:seed создаёт служебные счета банка, учётные записи сотрудников и двух демонстрационных клиентов, обучает начальную модель скоринга и загружает курсы валют с сайта Национального банка. Сервер запускается командой npm start.')
    b.unit('install', [
        'Каждая команда сообщает о результате своей работы.',
        'После запуска сервер выводит адрес, по которому приложение открывается в браузере, по умолчанию http://localhost:3000, а также сообщает, настроена ли отправка писем и как часто создаются резервные копии. Остановить сервер можно сочетанием клавиш Ctrl+C.',
    ], 'fig-guide-install.png', 'Создание базы данных и запуск сервера')
    b.text('Основные параметры задаются в файле .env. Параметр DATABASE_URL содержит адрес базы данных, логин и пароль, PORT – порт сервера, DATA_KEY – ключ шифрования паспортных данных и резервных копий, без которого их невозможно расшифровать, поэтому его нужно хранить отдельно от базы данных. Параметры BACKUP_DIR, BACKUP_KEEP и BACKUP_INTERVAL_HOURS задают каталог, число хранимых резервных копий и период их создания. Чтобы коды подтверждения и уведомления приходили на электронную почту, указываются параметры почтового сервера SMTP_HOST, SMTP_PORT, SMTP_USER и SMTP_PASS, без них приложение работает в учебном режиме и показывает коды на странице.')
    b.text('Для демонстрации команда npm run db:demo добавляет в кабинеты операции, вклад, кредит, заявку на кредит, задержанный перевод и анкету нового клиента. У всех демонстрационных пользователей пароль Taler2026: клиенты anna и igor, операционист operator, кредитный специалист credit, специалист по финансовому мониторингу monitor и администратор admin. Сотрудники при первом входе настраивают двухфакторную защиту. Работоспособность установки проверяется командой npm test, которая запускает программные тесты на отдельной тестовой базе данных.')

    b.h2('4.2 Руководство пользователя')
    for item in GUIDE:
        if item[0] == 'lead':
            b.text(item[1]); continue
        key, before, _, after, caption = item
        b.unit(key, [before, after], f'fig-guide-{key}.png', caption)
    b.text('Таким образом, интерфейс программного средства построен единообразно для всех ролей, а состав доступных разделов определяется правами роли пользователя. Все операции, изменяющие данные, выполняются с проверкой прав на сервере и записываются в журнал аудита.')
    b.save(out)


if __name__ == '__main__':
    out = sys.argv[1] if len(sys.argv) > 1 else os.path.join(KURS, 'razdel-4.docx')
    build(out)
    print(out)
